// 从Merge节点获取数据 - input1是本月，input2是上月
const currentMonth = $('读取本月Excel').all().map(item => item.json);
const lastMonth = $('读取上月Excel').all().map(item => item.json);

// 创建上月数据映射 - 使用Resource作为key
const lastMonthMap = new Map();
lastMonth.forEach(item => {
  const key = item.Resource || item.ResourceId || item['资源'];
  const cost = parseFloat(item.Cost || item.CostUSD || item['费用'] || 0);

  if (key) {
    lastMonthMap.set(key, {
      cost: cost,
      resourceGroup: item.ResourceGroup || item['资源组'] || '',
      resourceType: item.ResourceType || item['资源类型'] || ''
    });
  }
});

// 对比并生成结果
const results = [];
const processedKeys = new Set();

currentMonth.forEach(item => {
  const key = item.Resource || item.ResourceId || item['资源'];
  const currentCost = parseFloat(item.Cost || item.CostUSD || item['费用'] || 0);
  const resourceGroup = item.ResourceGroup || item['资源组'] || '';
  const resourceType = item.ResourceType || item['资源类型'] || '';

  if (!key) return;

  const lastData = lastMonthMap.get(key);
  const lastCost = lastData ? lastData.cost : 0;
  const diff = currentCost - lastCost;
  const percentChange = lastCost !== 0 ? ((diff / lastCost) * 100).toFixed(2) : (currentCost > 0 ? 'NEW' : '0');

  results.push({
    '资源组': resourceGroup,
    '资源名称': key,
    '资源类型': resourceType,
    '本月费用': currentCost.toFixed(2),
    '上月费用': lastCost.toFixed(2),
    '差额': diff.toFixed(2),
    '变化%': percentChange === 'NEW' ? '新增' : percentChange + '%',
    '状态': diff > 0 ? '↑增加' : diff < 0 ? '↓减少' : '→持平',
    '_sort': Math.abs(diff)
  });

  processedKeys.add(key);
  lastMonthMap.delete(key);
});

// 添加已删除的资源
lastMonthMap.forEach((data, key) => {
  results.push({
    '资源组': data.resourceGroup,
    '资源名称': key,
    '资源类型': data.resourceType,
    '本月费用': '0.00',
    '上月费用': data.cost.toFixed(2),
    '差额': (-data.cost).toFixed(2),
    '变化%': '-100%',
    '状态': '✕已删除',
    '_sort': data.cost
  });
});

// 按差额绝对值排序
results.sort((a, b) => b._sort - a._sort);
results.forEach(r => delete r._sort);

// 计算汇总
const totalCurrent = results.reduce((s, r) => s + parseFloat(r['本月费用']), 0);
const totalLast = results.reduce((s, r) => s + parseFloat(r['上月费用']), 0);
const totalDiff = totalCurrent - totalLast;
const totalPercent = totalLast !== 0 ? ((totalDiff / totalLast) * 100).toFixed(2) : 'N/A';

// 统计信息
const stats = {
  increase: results.filter(r => r['状态'] === '↑增加').length,
  decrease: results.filter(r => r['状态'] === '↓减少').length,
  newItems: results.filter(r => r['变化%'] === '新增').length,
  deleted: results.filter(r => r['状态'] === '✕已删除').length
};

// 插入汇总行
results.unshift(
  {
    '资源组': '══════════',
    '资源名称': '汇总统计',
    '资源类型': '══════════',
    '本月费用': totalCurrent.toFixed(2),
    '上月费用': totalLast.toFixed(2),
    '差额': totalDiff.toFixed(2),
    '变化%': totalPercent === 'N/A' ? 'N/A' : totalPercent + '%',
    '状态': totalDiff > 0 ? '▲总体增加' : totalDiff < 0 ? '▼总体减少' : '━持平'
  },
  {
    '资源组': '',
    '资源名称': `变化明细: 增${stats.increase} | 减${stats.decrease} | 新${stats.newItems} | 删${stats.deleted}`,
    '资源类型': '',
    '本月费用': '',
    '上月费用': '',
    '差额': '',
    '变化%': '',
    '状态': ''
  },
  {
    '资源组': '──────────',
    '资源名称': '──────────',
    '资源类型': '──────────',
    '本月费用': '──────────',
    '上月费用': '──────────',
    '差额': '──────────',
    '变化%': '──────────',
    '状态': '──────────'
  }
);

return results.map(r => ({ json: r }));
